    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
       javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
       
       String medicine = jComboBox1.getSelectedItem().toString();
       int quantity = Integer.parseInt(jSpinner1.getValue().toString());
       double unitprice = Double.parseDouble(jTextField2.getText());
       
       double totalPrice = quantity * unitprice;
       
       if (!jTextField2.getText().isEmpty()) 
      {
          Object[] medRow = { medicine, quantity, totalPrice };
          model.addRow(medRow);
      }
       
     
       if (jRadioButton1.isSelected())
       { 
        Object[] vac1Row = { "Vaccine 1", "1", "500.0" }; 
        model.addRow(vac1Row);
       }
       
       if (jRadioButton3.isSelected())
       { 
        Object[] vac2Row = { "Vaccine 2", "1", "750.0" };
        model.addRow(vac2Row);
       }
       
       if (jRadioButton5.isSelected())
       { 
        Object[] vac3Row = { "Vaccine 3", "1", "1000.0" };
        model.addRow(vac3Row);
       }
       
       
       
       
       
    }//GEN-LAST:event_jButton1ActionPerformed

