    private void jComboBox1ItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_jComboBox1ItemStateChanged
        if (evt.getStateChange() == java.awt.event.ItemEvent.SELECTED) 
        {
            String selectedMedicine = jComboBox1.getSelectedItem().toString();
            
            double price = 0.0;
            if(selectedMedicine.equals("Amoxicillin"))
            {
                price = 1200.0;
            }
            if(selectedMedicine.equals("Meloxicam"))
            {
                price = 1000.0;
            }
            if(selectedMedicine.equals("Rimadyl"))
            {
                price = 650.0;
            }
            if(selectedMedicine.equals("Selamectin"))
            {
                price = 300.0;
            }
            if(selectedMedicine.equals("Bravecto"))
            {
                price = 700.0;
            }
            if(selectedMedicine.equals("NexGard"))
            {
                price = 550.0;
            }
            
            jTextField2.setText(String.valueOf(price));
            
            
        }
    }//GEN-LAST:event_jComboBox1ItemStateChanged

    private void jButton3ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton3ActionPerformed
       javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
       double totalSum = 0.0;
       
       
       for (int i = 0; i < model.getRowCount(); i++)
       {
           double price = Double.parseDouble(model.getValueAt(i, 2).toString());
           totalSum += price;
       }
       jTextField4.setText(String.valueOf(totalSum));
    }//GEN-LAST:event_jButton3ActionPerformed

