    private void jButton4ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton4ActionPerformed
      javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
      int selectedRow = jTable1.getSelectedRow();
      
      if (selectedRow >= 0)
      {
          model.removeRow(selectedRow);
          javax.swing.JOptionPane.showMessageDialog(this, "Selected item deleted successfully!");
      }
      
      else 
      {
          javax.swing.JOptionPane.showMessageDialog(this, "Please select a row in the table to delete!", "Error", javax.swing.JOptionPane.WARNING_MESSAGE);
      }
    }//GEN-LAST:event_jButton4ActionPerformed

    private void jButton5ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton5ActionPerformed
       
       String Date = jTextField3.getText(); 
       String ownerId = jTextField1.getText();
       String petName = jTextField5.getText();
       String medicine =jComboBox1.getSelectedItem().toString();
       String quantity = jSpinner1.getValue().toString();
       String unit =jTextField2.getText();
       String totalBill = jTextField4.getText();
       
       javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
       
       if (Date.isEmpty()||ownerId.isEmpty() || petName.isEmpty() ||medicine.isEmpty()||quantity.isEmpty()||unit.isEmpty()||totalBill.isEmpty()|| model.getRowCount() == 0)
       {
        javax.swing.JOptionPane.showMessageDialog(this, "Please fill fields and add items to the table first!");
       }
       
       else
       {
           try
           {
               controller.PaymentController ctrl = new controller.PaymentController();
                boolean success = ctrl.savePaymentData(Date, ownerId, petName, medicine, quantity, unit, Double.parseDouble(totalBill));
                
                if (success) {
                    javax.swing.JOptionPane.showMessageDialog(this, "All Details Saved Successfully to Database!");
                } else {
                    javax.swing.JOptionPane.showMessageDialog(this, "Database Error!", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
                }
           }
           catch (Exception e)
           {
               e.printStackTrace();
               javax.swing.JOptionPane.showMessageDialog(this, "Error: " + e.getMessage(), "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
            
           }
       }
           
       
       
    }//GEN-LAST:event_jButton5ActionPerformed

